    /// <summary>
    ///
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataFieldEventHandler(formDataFieldStr(LedgerJournalTransVendInvoice, LedgerJournalTrans, Payment), FormDataFieldEventType::Modified)]
    public static void Payment_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        LedgerJournalEngine         ledgerJournalEngine;
        LedgerJournalTable          ledgerJournalTable;
        NoYesCombo                  paymDate;
        PaymTerm                    paymTerm;
        PaymMethod                  paymMethod;

        FormDataSource ledgerJournalTrans_ds = sender.datasource();

        //Ledger Journal Trans table buffer
        LedgerJournalTrans  ledgerJournalTrans = sender.datasource().cursor();
        
        FormRun element = sender.datasource().formRun();

        //TODO: move all the repetitive code to a new class - METLedgerJournalTransDueDtProcess
        //METLedgerJournalTransDueDtProcess   ledgerJournalTransdueDtProcess;

        //Ledger Journal Table buffer
        ledgerJournalTable = LedgerJournalTable::find(ledgerJournalTrans.JournalNum);

        //LedgerJournal Engine used to determine if the invoice is a vendor invoice
        ledgerJournalEngine = LedgerJournalEngine::construct(LedgerJournalType::VendInvoice,element);

        //TODO: move all the repetitive code to a new class - METLedgerJournalTransDueDtProcess
        //ledgerJournalTransdueDtProcess = METLedgerJournalTransDueDtProcess::construct();

        //Payment Date Toogle Control setting in Ledger Journal Name Screen
        paymDate = LedgerJournalName::find(ledgerJournalTable.JournalName).METPaymDate;

        //Terms OF Payment
        paymTerm = PaymTerm::find(ledgerJournalTrans.Payment);
        
        //Verify if the toogle control is set to Yes
        if(paymDate == NoYesCombo::Yes)
        {
            if(!ledgerJournalTrans.Invoice || ledgerJournalTrans.Invoice)
            {
                //Due Date Calculation based on the Transaction Date when the Payment Date option in Journal Name Is Set To Yes
                ledgerJournalTrans.Due = paymTerm.due(ledgerJournalTrans.TransDate,paymTerm.PaymDayId);
            }
        }
    }

    /// <summary>
    /// Dimension default Modified event handler
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataFieldEventHandler(formDataFieldStr(LedgerJournalTransVendInvoice, LedgerJournalTrans, DefaultDimension), FormDataFieldEventType::Modified)]
    public static void DefaultDimension_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        LedgerJournalEngine         ledgerJournalEngine;
        LedgerJournalTable          ledgerJournalTable;
        NoYesCombo                  paymDate;
        PaymTerm                    paymTerm;
        PaymMethod                  paymMethod;

        //Datasource buffer
        FormDataSource ledgerJournalTrans_ds = sender.datasource();

        //Ledger Journal Trans table buffer
        LedgerJournalTrans  ledgerJournalTrans = sender.datasource().cursor();
        
        FormRun element = sender.datasource().formRun();

        //TODO: move all the repetitive code to a new class - METLedgerJournalTransDueDtProcess
        //METLedgerJournalTransDueDtProcess   ledgerJournalTransdueDtProcess;

        //Ledger Journal Table buffer
        ledgerJournalTable = LedgerJournalTable::find(ledgerJournalTrans.JournalNum);

        //LedgerJournal Engine used to determine if the invoice is a vendor invoice
        ledgerJournalEngine = LedgerJournalEngine::construct(LedgerJournalType::VendInvoice,element);

        //TODO: move all the repetitive code to a new class - METLedgerJournalTransDueDtProcess
        //ledgerJournalTransdueDtProcess = METLedgerJournalTransDueDtProcess::construct();
        
        //Payment Date Toogle Control setting in Ledger Journal Name Screen
        paymDate = LedgerJournalName::find(ledgerJournalTable.JournalName).METPaymDate;

        //Terms OF Payment
        paymTerm = PaymTerm::find(ledgerJournalTrans.Payment);
        
        //Verify if the toogle control is set to Yes
        if(paymDate == NoYesCombo::Yes)
        {
            if(!ledgerJournalTrans.Invoice || ledgerJournalTrans.Invoice)
            {
                //Due Date Calculation based on the Transaction Date when the Payment Date option in Journal Name Is Set To Yes
                ledgerJournalTrans.Due = paymTerm.due(ledgerJournalTrans.TransDate,paymTerm.PaymDayId);
            }
        }

    }
